import{_ as e,c as d,o,a7 as c}from"./chunks/framework.BxaL7nSC.js";const f=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/middleware/auth/configuration.md","filePath":"guide/middleware/auth/configuration.md","lastUpdated":1792272438000}'),r={name:"guide/middleware/auth/configuration.md"};function i(n,t,a,s,l,u){return o(),d("div",null,[...t[0]||(t[0]=[c('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><h2 id="auth-config" tabindex="-1">Auth Config <a class="header-anchor" href="#auth-config" aria-label="Permalink to “Auth Config”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>Base</code></td><td><code>string</code></td><td><code>&quot;/&quot;</code></td><td>URL prefix for all auth routes</td></tr><tr><td><code>UI.Title</code></td><td><code>string</code></td><td><code>&quot;Sign in&quot;</code></td><td>Title shown on login page</td></tr><tr><td><code>UI.Subtitle</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Text below the title</td></tr><tr><td><code>UI.Icon</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Logo URL, data URI, inline SVG, or filename in embedded FS</td></tr><tr><td><code>UI.Version</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Version text shown in header</td></tr><tr><td><code>UI.ExternalFolder</code></td><td><code>bool</code></td><td><code>false</code></td><td>Use your own login page instead of embedded UI</td></tr><tr><td><code>UI.SignupFirst</code></td><td><code>bool</code></td><td><code>false</code></td><td>Land on the signup form instead of login (first-run bootstrap)</td></tr><tr><td><code>UI.Theme</code></td><td><code>map[string]string</code></td><td><code>nil</code></td><td>CSS variable overrides applied to <code>:root</code> at load (e.g. <code>{&quot;btn-bg&quot;: &quot;#3b82f6&quot;}</code>)</td></tr><tr><td><code>UI.CustomCSSURL</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>URL of a stylesheet appended to the login page for full restyling</td></tr><tr><td><code>CookieName</code></td><td><code>string</code></td><td><code>&quot;auth_session&quot;</code></td><td>Session cookie name</td></tr><tr><td><code>Cookie.Path</code></td><td><code>string</code></td><td><code>&quot;/&quot;</code></td><td>Cookie path</td></tr><tr><td><code>Cookie.MaxAge</code></td><td><code>int</code></td><td><code>0</code></td><td>Cookie max-age in seconds</td></tr><tr><td><code>Cookie.Domain</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>Cookie domain</td></tr><tr><td><code>Cookie.Secure</code></td><td><code>cookie.SecureMode</code></td><td><code>auto</code></td><td><code>auto</code> (set when the request is HTTPS), <code>always</code>, or <code>never</code></td></tr><tr><td><code>Cookie.DisableHTTPOnly</code></td><td><code>bool</code></td><td><code>false</code></td><td>Expose the cookie to JavaScript. <strong>HttpOnly is on by default</strong></td></tr><tr><td><code>Cookie.SameSite</code></td><td><code>http.SameSite</code></td><td><code>Lax</code></td><td>Cookie SameSite policy</td></tr><tr><td><code>IssuerConfig.AccessTTL</code></td><td><code>time.Duration</code></td><td><code>15m</code></td><td>Access token lifetime, clamped to <code>RefreshTTL</code></td></tr><tr><td><code>IssuerConfig.RefreshTTL</code></td><td><code>time.Duration</code></td><td><code>7d</code></td><td>Refresh token and maximum session lifetime</td></tr><tr><td><code>IssuerConfig.DisableRefreshRotation</code></td><td><code>bool</code></td><td><code>false</code></td><td>Turn off refresh rotation. <strong>Rotation is on by default</strong></td></tr><tr><td><code>MFA.CookieName</code></td><td><code>string</code></td><td><code>&quot;auth_mfa&quot;</code></td><td>Pending-login cookie (only used with <code>WithSecondFactor</code>)</td></tr><tr><td><code>MFA.TTL</code></td><td><code>time.Duration</code></td><td><code>5m</code></td><td>How long the user has to complete the second factor</td></tr><tr><td><code>MFA.MaxAttempts</code></td><td><code>int</code></td><td><code>5</code></td><td>Wrong codes tolerated before the pending login is destroyed</td></tr><tr><td><code>ProtectedResource</code></td><td><code>*resource.Config</code></td><td><code>nil</code></td><td>Publish RFC 9728 metadata. See <a href="./resource-server.html">Resource Server</a></td></tr><tr><td><code>DisableRequestAuth</code></td><td><code>bool</code></td><td><code>false</code></td><td>Turn off request-credential auth in <code>Require()</code>, restoring cookie-only gating</td></tr></tbody></table><p><code>Cookie.Secure</code> defaults to <code>auto</code>: the <code>Secure</code> attribute is set when the request arrived over TLS, directly or via <code>X-Forwarded-Proto</code>. That protects real deployments without breaking <code>http://localhost</code>. Pin it to <code>always</code> when TLS terminates upstream and the proxy forwards no protocol hint.</p><h2 id="oauth2-config" tabindex="-1">OAuth2 Config <a class="header-anchor" href="#oauth2-config" aria-label="Permalink to “OAuth2 Config”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>IssuerURL</code></td><td><code>string</code></td><td><code>&quot;&quot;</code></td><td>OIDC issuer URL for auto-discovery</td></tr><tr><td><code>ClientID</code></td><td><code>string</code></td><td>required</td><td>OAuth2 client ID</td></tr><tr><td><code>ClientSecret</code></td><td><code>string</code></td><td>required</td><td>OAuth2 client secret</td></tr><tr><td><code>Scopes</code></td><td><code>[]string</code></td><td><code>[]</code></td><td>Requested scopes</td></tr><tr><td><code>AuthURL</code></td><td><code>string</code></td><td>auto</td><td>Authorization endpoint</td></tr><tr><td><code>TokenURL</code></td><td><code>string</code></td><td>auto</td><td>Token endpoint</td></tr><tr><td><code>UserInfoURL</code></td><td><code>string</code></td><td>auto</td><td>UserInfo endpoint</td></tr><tr><td><code>RevocationURL</code></td><td><code>string</code></td><td>auto</td><td>Token revocation endpoint</td></tr><tr><td><code>LogoutURL</code></td><td><code>string</code></td><td>auto</td><td>End-session endpoint</td></tr><tr><td><code>JWKSURL</code></td><td><code>string</code></td><td>auto</td><td>Key set used to verify the <code>id_token</code> signature</td></tr><tr><td><code>Audience</code></td><td><code>string</code></td><td><code>ClientID</code></td><td>Value required in the <code>id_token</code> <code>aud</code> claim</td></tr><tr><td><code>ClockSkew</code></td><td><code>time.Duration</code></td><td><code>60s</code></td><td>Tolerance applied to <code>exp</code> / <code>nbf</code></td></tr><tr><td><code>DisablePKCE</code></td><td><code>bool</code></td><td><code>false</code></td><td>Disable PKCE (not recommended)</td></tr><tr><td><code>DisableNonce</code></td><td><code>bool</code></td><td><code>false</code></td><td>Omit the OIDC <code>nonce</code> (not recommended)</td></tr><tr><td><code>SkipIDTokenVerify</code></td><td><code>bool</code></td><td><code>false</code></td><td>Accept an unverified <code>id_token</code>. <strong>Do not set this</strong></td></tr><tr><td><code>PasswordFlow</code></td><td><code>bool</code></td><td><code>false</code></td><td>Enable resource owner password flow</td></tr><tr><td><code>AuthHeaderStyle</code></td><td><code>int</code></td><td><code>0</code> (Basic)</td><td><code>0</code>=Basic, <code>1</code>=Bearer, <code>2</code>=Params</td></tr></tbody></table><h2 id="id-token-verification" tabindex="-1">ID token verification <a class="header-anchor" href="#id-token-verification" aria-label="Permalink to “ID token verification”">​</a></h2><p>An <code>id_token</code>, when present, is always verified: RS/PS/ES/EdDSA signature against the IdP&#39;s JWKS, then <code>iss</code>, <code>aud</code>, <code>exp</code>, <code>nbf</code> and <code>nonce</code>.</p><p>Claims are taken from <code>UserInfoURL</code> when it is configured, otherwise from the verified <code>id_token</code>. With neither — no userinfo endpoint and no reachable key set — the login <strong>fails</strong> rather than falling back to an unverified payload. <code>SkipIDTokenVerify</code> exists for the single case of an IdP that publishes no key set on a trusted channel; it turns the <code>id_token</code> into an unauthenticated assertion of whatever the caller wants.</p><p>JWKS keys are cached. A successful fetch starts the normal one-minute refresh cooldown used to prevent unknown-key requests from amplifying traffic to the IdP. A failed fetch instead uses a bounded two-second retry backoff, so a brief provider outage does not suppress retries for a full minute. Concurrent misses share one refresh, while lookups of cached keys continue without waiting for the IdP. JWKS requests use the caller or configured client timeout, with a 30-second fallback only when neither supplies a deadline. An ID token with no <code>kid</code> is accepted only when the JWKS has exactly one usable key; with multiple keys it fails immediately as ambiguous without another fetch.</p><p>State, nonce and the PKCE verifier live together in one <code>HttpOnly</code> cookie (<code>auth_flow_&lt;name&gt;</code>), cleared after a single use. Override its attributes with <code>Options.FlowCookie</code> if the callback lands on a different subdomain.</p><h2 id="routes" tabindex="-1">Routes <a class="header-anchor" href="#routes" aria-label="Permalink to “Routes”">​</a></h2><p>With default <code>Base: &quot;/&quot;</code>:</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td>GET</td><td><code>/login/</code></td><td>Login UI (embedded Svelte or external folder)</td></tr><tr><td>GET</td><td><code>/login/info</code></td><td>JSON: title, subtitle, icon, version, strategies</td></tr><tr><td>GET</td><td><code>/login/me</code></td><td>Current user&#39;s Identity as JSON</td></tr><tr><td>GET/POST</td><td><code>/login/pass/{strategy}</code></td><td>Initiate or submit login</td></tr><tr><td>POST</td><td><code>/login/register/{strategy}</code></td><td>Create an account (strategy must implement <code>Registerer</code>)</td></tr><tr><td>GET</td><td><code>/login/callback/{strategy}</code></td><td>OAuth2 redirect callback</td></tr><tr><td>POST</td><td><code>/login/refresh</code></td><td>Force-refresh access token</td></tr><tr><td>POST</td><td><code>/login/mfa</code></td><td>Complete a second factor (only with <code>WithSecondFactor</code>)</td></tr><tr><td>POST</td><td><code>/logout</code></td><td>Revoke session and clear cookie</td></tr><tr><td>GET</td><td><code>/login/status</code></td><td>Status iframe (for popup flow)</td></tr><tr><td>GET</td><td><code>/.well-known/oauth-protected-resource[/…]</code></td><td>RFC 9728 metadata, only when <code>ProtectedResource</code> is set. Mounted at the origin, not under <code>Base</code>, and never behind <code>Require()</code></td></tr></tbody></table><h3 id="request-body-limits" tabindex="-1">Request body limits <a class="header-anchor" href="#request-body-limits" aria-label="Permalink to “Request body limits”">​</a></h3><p>Auth endpoints enforce the following request-body caps:</p><table tabindex="0"><thead><tr><th>Request</th><th style="text-align:right;">Limit</th></tr></thead><tbody><tr><td>Local login and registration</td><td style="text-align:right;">64 KiB</td></tr><tr><td>LDAP login</td><td style="text-align:right;">64 KiB</td></tr><tr><td>Magic-link request</td><td style="text-align:right;">64 KiB</td></tr><tr><td>OAuth2 password form</td><td style="text-align:right;">64 KiB</td></tr><tr><td>TOTP second factor</td><td style="text-align:right;">16 KiB</td></tr><tr><td>Passkey login begin or finish</td><td style="text-align:right;">128 KiB</td></tr></tbody></table><p>An oversized body receives JSON <code>413 Content Too Large</code> with error code <code>body_too_large</code>; its message includes the applicable byte limit. The body is rejected before JSON or form parsing, so it is not misreported as malformed input.</p><p><code>POST /login/refresh</code> rotates the server-side token pair and returns <code>{&quot;identity&quot;: ...}</code>. It no longer returns <code>session_id</code>; the opaque session ID remains confined to the <code>HttpOnly</code> cookie and clients must not expect it in the JSON response.</p>',19)])])}const g=e(r,[["render",i]]);export{f as __pageData,g as default};
